import json, urllib.request, urllib.error, time

def call(method, path, body=None, timeout=30):
    req = urllib.request.Request(f"https://api.ivxholding.com{path}",
        data=json.dumps(body).encode() if body is not None else None,
        headers={"Content-Type": "application/json", "Accept": "application/json"}, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        try: return e.code, json.loads(e.read() or b"{}")
        except Exception: return e.code, {}

code, res = call("POST", "/api/ivx/agents/certificate/run", {"ownerApprovalToken": "owner-recert-post-e2e-audit"})
print(f"cert run: HTTP {code} ok={res.get('ok')} runId={res.get('runId')}")
for i in range(5):
    _, pr = call("GET", "/api/ivx/agents/certificate/progress")
    p = pr.get("activeRun") or {}
    print(f"poll {i}: {p.get('status')} phase={p.get('phase')} {p.get('processed')}/{p.get('total')} failed={p.get('failed')}")
    if p.get("status") in ("completed", "failed"): break
    time.sleep(9)
